/**
 * Saca nombre, email y plan del texto del mensaje.
 *
 * El mensaje precargado de la web (RECEIPT_MESSAGE en src/lib/site.ts) pide los
 * datos con etiquetas exactas. Se parsea eso primero, y si no aparece se cae a
 * una búsqueda suelta: mucha gente borra la plantilla y escribe a mano.
 */
const msg = $input.first().json;
const texto = String(msg.texto ?? '');

const etiqueta = (nombre) => {
  const m = texto.match(new RegExp(`mi\\s*${nombre}\\s*:\\s*(.+)`, 'i'));
  return m ? m[1].trim() : '';
};

const emailSuelto = (texto.match(/[\w.+-]+@[\w-]+\.[\w.]+/) ?? [''])[0];

// El nombre del perfil de WhatsApp es un buen segundo premio: no siempre es el
// nombre real, pero sirve para que Pía sepa a quién está mirando.
const nombre = etiqueta('nombre') || String(msg.perfil ?? '').trim();
const email = (etiqueta('email') || emailSuelto).toLowerCase().trim();

// El plan se normaliza a los dos ids que entiende src/lib/products.ts. Si no se
// reconoce queda vacío y lo completa Pía: adivinar acá es adivinar con plata.
const planCrudo = (etiqueta('plan') || texto).toLowerCase();
let plan = '';
if (/\b3\b|tres\s*niveles|pack/.test(planCrudo)) plan = 'pack-3-niveles';
else if (/un\s*nivel|1\s*nivel|mensual/.test(planCrudo)) plan = 'nivel-mensual';

return [{ json: { ...msg, nombre, email, plan } }];

/**
 * El único nodo que piensa. Todo lo que viene después es tonto a propósito: si
 * mañana cambia una regla del cobro, se cambia acá y en ningún otro lado.
 */
const cfg = $('Configuración').first().json;
const msg = $('Leer los datos del mensaje').first().json;

// `alwaysOutputData` hace que una planilla vacía devuelva un item sin columnas.
const filas = $input.all()
  .map((i) => i.json)
  .filter((f) => f && f.codigo);

const soloDigitos = (t) => String(t ?? '').replace(/\D/g, '');
const TERMINALES = ['confirmado', 'rechazado', 'devuelto'];
const estaCerrada = (f) => TERMINALES.includes(String(f.estado ?? '').toLowerCase());

// La fila viva de este teléfono: la última que todavía no se cerró. Si una
// clienta ya compró y vuelve a escribir, empieza una venta nueva en vez de
// pisar la anterior — que es lo que corresponde cuando compra el nivel 2.
const abiertas = filas.filter(
  (f) => soloDigitos(f.whatsapp) === soloDigitos(msg.whatsapp) && !estaCerrada(f),
);
const actual = abiertas[abiertas.length - 1] ?? null;

/**
 * Código de 4 dígitos que no esté en uso. Se excluyen las ventas cerradas: un
 * código de hace seis meses puede reciclarse sin ambigüedad, porque A3-bis sólo
 * busca entre las pendientes.
 */
function nuevoCodigo() {
  const enUso = new Set(
    filas.filter((f) => !estaCerrada(f)).map((f) => String(f.codigo).padStart(4, '0')),
  );
  for (let intento = 0; intento < 200; intento++) {
    const c = String(Math.floor(1000 + Math.random() * 9000));
    if (!enUso.has(c)) return c;
  }
  throw new Error(
    'No se pudo generar un código libre en 200 intentos. Hay demasiadas ventas abiertas sin cerrar: revisá la planilla.',
  );
}

// Lo nuevo pisa a lo viejo sólo si trae contenido. Un segundo mensaje sin email
// no puede borrar el email que llegó en el primero.
const preferir = (nuevo, viejo) =>
  String(nuevo ?? '').trim() || String(viejo ?? '').trim();

const fila = {
  fecha: actual?.fecha || new Date().toISOString().slice(0, 10),
  codigo: actual?.codigo ? String(actual.codigo).padStart(4, '0') : nuevoCodigo(),
  nombre: preferir(msg.nombre, actual?.nombre),
  email: preferir(msg.email, actual?.email),
  whatsapp: soloDigitos(msg.whatsapp),
  plan: preferir(msg.plan, actual?.plan),
  monto: actual?.monto ?? '',
  moneda: 'ARS',
  metodo_pago: 'transferencia',
  comprobante_url: actual?.comprobante_url ?? '',
  estado: String(actual?.estado ?? 'esperando').toLowerCase(),
  grupo: actual?.grupo || cfg.grupoActual,
  acceso_skool: actual?.acceso_skool ?? 'no',
  fecha_llamada: actual?.fecha_llamada ?? '',
  garantia_vence: actual?.garantia_vence ?? '',
  notas: actual?.notas ?? '',
};

const traeAdjuntoNuevo = String(msg.adjuntoId ?? '') !== '';
const tieneComprobante = traeAdjuntoNuevo || fila.comprobante_url !== '';

const faltan = [];
if (!fila.nombre) faltan.push('tu nombre');
if (!fila.email) faltan.push('tu email');
if (!tieneComprobante) faltan.push('la foto del comprobante');

let accion;
if (fila.estado === 'pendiente') {
  // Ya se le avisó a Pía. Cualquier mensaje nuevo se acusa, pero NO vuelve a
  // notificar: si no, un reenvío le llena el WhatsApp de avisos repetidos.
  accion = 'ya_avisado';
} else if (faltan.length === 0) {
  fila.estado = 'pendiente';
  accion = traeAdjuntoNuevo ? 'completar_con_adjunto' : 'completar_sin_adjunto';
} else {
  accion = 'faltan_datos';
}

// "tu nombre, tu email y la foto del comprobante" — con la coma de Oxford al revés,
// que es como se escribe en castellano.
const faltanTexto = faltan.length > 1
  ? `${faltan.slice(0, -1).join(', ')} y ${faltan[faltan.length - 1]}`
  : faltan[0] ?? '';

return [{
  json: { accion, faltan, faltanTexto, esNueva: actual === null, adjuntoId: msg.adjuntoId ?? '', ...fila },
}];

// Le pega el link de Drive a la fila que armó "Decidir" y descarta los campos
// de trabajo: a la planilla va la fila y nada más.
const fila = { ...$('Decidir').first().json };
const archivo = $input.first().json;

fila.comprobante_url =
  archivo.webViewLink ||
  (archivo.id ? `https://drive.google.com/file/d/${archivo.id}/view` : '');

for (const campo of ['accion', 'faltan', 'faltanTexto', 'esNueva', 'adjuntoId']) {
  delete fila[campo];
}

return [{ json: fila }];

// El comprobante ya estaba guardado de un mensaje anterior. Se limpia la fila
// igual que en la otra rama, para que las dos escriban exactamente lo mismo.
const fila = { ...$('Decidir').first().json };

for (const campo of ['accion', 'faltan', 'faltanTexto', 'esNueva', 'adjuntoId']) {
  delete fila[campo];
}

return [{ json: fila }];

