    components: [{
      type: 'body',
      parameters: [
        { type: 'text', text: $json.nombre || 'sin nombre' },
        { type: 'text', text: $json.email || 'sin email' },
        { type: 'text', text: $json.plan || 'sin especificar' },
        { type: 'text', text: $json.comprobante_url || 'sin link' },
        { type: 'text', text: $json.codigo }
      ]
    }]
  }
}) }}
